64: /** Top-level entry point: parses the Discourse cooked HTML body into a typed block list. */
65: fun parseCookedPostBody(html: String, baseUrl: String): List<CookedPostBlock> {
66:     val body = Jsoup.parseBodyFragment(html).body()
67:     val raw = body.children().flatMap { element -> parseCookedElement(element) }
68:     val blocks = coalesceImagesIntoCollage(raw)
69:     return blocks.ifEmpty {
70:         body.text().takeIf { it.isNotBlank() }?.let { text ->
71:             listOf(CookedPostBlock.Text("<p>$text</p>"))
72:         }.orEmpty()
73:     }
74: }
