76: // Telegram TL_pageBlockCollage delivers a typed list of photo
77: // blocks from the server. Discourse cooked HTML emits them as adjacent <p> /
78: // .lightbox-wrapper images, so we coalesce 2+ adjacent Image blocks into a
79: // Collage and let the renderer lay them out as a 2-column grid.
80: private fun coalesceImagesIntoCollage(blocks: List<CookedPostBlock>): List<CookedPostBlock> {
81:     if (blocks.size < 2) return blocks
82:     val out = mutableListOf<CookedPostBlock>()
83:     var i = 0
84:     while (i < blocks.size) {
85:         val block = blocks[i]
86:         if (block is CookedPostBlock.Image) {
87:             var j = i + 1
88:             val group = mutableListOf(block)
89:             while (j < blocks.size && blocks[j] is CookedPostBlock.Image) {
90:                 group.add(blocks[j] as CookedPostBlock.Image)
91:                 j++
92:             }
93:             if (group.size >= 2) {
94:                 out.add(CookedPostBlock.Collage(images = group.toList()))
95:             } else {
96:                 out.add(block)
97:             }
98:             i = j
99:         } else {
100:             out.add(block)
101:             i++
102:         }
103:     }
104:     return out
105: }
