107: private fun parseCookedElement(element: Element): List<CookedPostBlock> {
108:     return when (element.normalName()) {
109:         "p" -> parseParagraphElement(element)
110:         "blockquote" -> element.html()
111:             .takeIfHtmlNotBlank()
112:             ?.let { listOf(CookedPostBlock.Quote(title = null, html = it)) }
113:             .orEmpty()
114:         "aside" -> parseAsideElement(element)
115:         "pre" -> listOf(
116:             CookedPostBlock.Code(
117:                 (element.selectFirst("code")?.wholeText() ?: element.wholeText()).trimEnd(),
118:             ),
119:         )
120:         "ul", "ol" -> parseListElement(element)
121:         "details" -> parseDetailsElement(element)
122:         "h1" -> listOf(CookedPostBlock.Heading(level = 1, html = element.html()))
123:         "h2" -> listOf(CookedPostBlock.Heading(level = 2, html = element.html()))
124:         "h3" -> listOf(CookedPostBlock.Heading(level = 3, html = element.html()))
125:         "h4" -> listOf(CookedPostBlock.Heading(level = 4, html = element.html()))
126:         "h5" -> listOf(CookedPostBlock.Heading(level = 5, html = element.html()))
127:         "h6" -> listOf(CookedPostBlock.Heading(level = 6, html = element.html()))
128:         "hr" -> listOf(CookedPostBlock.Rule)
129:         "table" -> parseTableElement(element)
130:         "div" -> parseDivElement(element)
131:         else -> element.html().takeIf { it.isNotBlank() }
132:             ?.let { listOf(CookedPostBlock.Text(it)) }
133:             .orEmpty()
134:     }
135: }
