146: private fun parseAsideElement(element: Element): List<CookedPostBlock> {
147:     if (element.hasClass("quote")) {
148:         val title = element.selectFirst(".title")?.text()?.takeIf { it.isNotBlank() }
149:         val quoteHtml = element.selectFirst("blockquote")?.html()?.takeIfHtmlNotBlank()
150:             ?: element.html()
151:         return listOf(CookedPostBlock.Quote(title = title, html = quoteHtml))
152:     }
153:     if (element.hasClass("onebox")) {
154:         val onebox = parseOneboxAside(element)
155:         if (onebox != null) return listOf(onebox)
156:     }
157:     val link = element.selectFirst("a[href]")
158:     val title = link?.text()?.takeIf { it.isNotBlank() }
159:     val href = link?.attr("href").orEmpty()
160:     val bodyText = element.selectFirst("article")?.html()?.takeIfHtmlNotBlank()
161:     return listOfNotNull(
162:         title?.let { CookedPostBlock.Text("<p><a href=\"$href\">$it</a></p>") },
163:         bodyText?.let(CookedPostBlock::Text),
164:     ) + imageBlocksFrom(element)
165: }
